/**
 * LEGADO DESATIVADO (consolidação WhatsApp + Typebot / FASE 4B).
 * Confirmação de pagamento NÃO passa mais pelo n8n nem por payment_status="paid".
 * Caminho oficial: Stripe → POST /api/webhooks/stripe (backend).
 */
const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const correlationId =
  headers['x-correlation-id'] ||
  headers['X-Correlation-Id'] ||
  body.correlation_id ||
  `pay-legacy-${Date.now()}`;

return [{
  json: {
    success: false,
    deprecated: true,
    official_entry: 'POST /api/webhooks/stripe',
    error:
      'Confirmação de pagamento via n8n desativada. Use o webhook Stripe oficial do backend.',
    correlationId,
    blocked_paths: [
      'POST /api/whatsapp/webhook com payment_status=paid',
      'payment_status=paid sem Stripe Checkout'
    ]
  }
}];
